const { buildSessionsWithTRIMP, estimateVO2maxFromRun } = require\('./calc'\);
const { loadData } = require\('./dataLoader'\);
const { getDb } = require\('./db'\);

const data = loadData\(\);
const { fc_repos, fc_max } = data.athlete;
const db = getDb\(\);
const dbLogs = db.prepare\('SELECT date, sport, distance_km, dplus_m, dplus_corrected, duration_min, fc_moy, extra_sessions_json FROM daily_logs ORDER BY date ASC'\).all\(\);
const sessions = buildSessionsWithTRIMP\(data.activities, dbLogs, fc_repos, fc_max\);

// Show top 10 VO2max estimates
const estimates = sessions
  .slice\(-50\)
  .map\(s => \({ 
    date: s.date, 
    km: s.km || s.distance_km, 
    dur: s.duration_min,
    hr: s.fc_moy,
    est: estimateVO2maxFromRun\(s.distance_km, s.duration_min, s.dplus_m, s.fc_moy, fc_repos, fc_max\)
  }\)\)
  .filter\(e => e.est\)
  .sort\(\(a,b\) => b.est - a.est\)
  .slice\(0, 10\);
console.log\('Top 10 VO2max estimates:'\);
estimates.forEach\(e => console.log\(JSON.stringify\(e\)\)\);

// Hill score analysis
const today = new Date\(\);
const cutoff = new Date\(today\); cutoff.setDate\(cutoff.getDate\(\) - 90\);
const hillSessions = sessions.filter\(s => new Date\(s.date\) >= cutoff && s.dplus_m > 0 && s.distance_km > 0 && \(s.dplus_m / s.distance_km\) >= 10\);
console.log\('\\nHill sessions \(90d\):', hillSessions.length\);
const totalRaw = hillSessions.reduce\(\(sum, s\) => sum + s.dplus_m, 0\);
const totalDecayed = hillSessions.reduce\(\(sum, s\) => {
  const daysAgo = \(today - new Date\(s.date\)\) / 86400000;
  return sum + s.dplus_m * Math.exp\(-daysAgo / 45\);
}, 0\);
console.log\('Total D+ \(raw\):', Math.round\(totalRaw\), 'm, decayed:', Math.round\(totalDecayed\)\);
console.log\('Max single session D+:', Math.max\(...hillSessions.map\(s => s.dplus_m\)\)\);
")

